# 2) Adapter from one-row-per-market production output to one-row-per-fixture Today cards.
p = Path("v5_ui_today.py")
text = p.read_text(encoding="utf-8")
marker = '\ndef prepare_today_board(board: pd.DataFrame) -> pd.DataFrame:\n'
if "def production_board_to_today" not in text:
    adapter = r'''\n\ndef _context_summary(first: pd.Series, fields: tuple[tuple[str, str], ...]) -> str:\n    parts = []\n    for label, name in fields:\n        value = _float_or_none(first.get(name))\n        if value is not None:\n            parts.append(f"{label} {value:+.3f}")\n    return " · ".join(parts) if parts else "Unavailable"\n\n\ndef _best_production_row(frame: pd.DataFrame) -> pd.Series | None:\n    if frame is None or frame.empty:\n        return None\n    ranked = frame.copy()\n    ranked["_sig"] = ranked.get("signal", pd.Series(index=ranked.index, dtype=object)).astype(str).str.upper().map(_SIGNAL_PRIORITY).fillna(9)\n    ranked["_ev"] = pd.to_numeric(ranked.get("expected_value"), errors="coerce").fillna(float("-inf"))\n    return ranked.sort_values(["_sig", "_ev"], ascending=[True, False], kind="stable").iloc[0]\n\n\ndef production_board_to_today(board: pd.DataFrame) -> pd.DataFrame:\n    """Collapse the frozen/full-context production market board into Today fixture cards.\n\n    No model is rerun here. Every probability, score projection, signal and context value is\n    copied from the production board that already used the accepted winner/score candidates.\n    """\n    if board is None or board.empty:\n        return pd.DataFrame()\n    from v5_core import american_from_prob\n    from v5_live_market import canonical_name\n\n    rows = []\n    fixture_col = "fixture_id" if "fixture_id" in board.columns else "Fixture ID"\n    for fixture_id, group in board.groupby(fixture_col, sort=False, dropna=False):\n        first = group.iloc[0]\n        p1 = str(first.get("resolved_player1") or first.get("player1") or "Player 1")\n        p2 = str(first.get("resolved_player2") or first.get("player2") or "Player 2")\n        p1_prob = _float_or_none(first.get("full_context_probability_p1"))\n        if p1_prob is None:\n            p1_prob = _float_or_none(first.get("calibrated_probability_p1"))\n        p2_prob = None if p1_prob is None else 1.0 - p1_prob\n        disagreement = str(first.get("model_disagreement") or "UNKNOWN").upper()\n        agreement = {"LOW":"HIGH", "MODERATE":"MODERATE", "HIGH":"LOW"}.get(disagreement, "UNKNOWN")\n\n        row = {\n            "Status":"OK", "Fixture ID":fixture_id, "Tournament":first.get("tournament"),\n            "Start":first.get("start_time_utc"), "Tour":first.get("tour_v5") or first.get("tour"),\n            "Surface":first.get("surface"), "Surface Source":first.get("surface_source"), "Best Of":first.get("best_of"),\n            "Player 1":p1, "Player 2":p2, "P1 V5 %":p1_prob, "P2 V5 %":p2_prob,\n            "P1 Fair":None if p1_prob is None else american_from_prob(p1_prob),\n            "P2 Fair":None if p2_prob is None else american_from_prob(p2_prob),\n            "Expected Margin":first.get("expected_margin"), "Expected Total":first.get("expected_total"),\n            "Agreement":agreement, "Model Disagreement":disagreement, "Model Gap":first.get("model_gap"),\n            "Winner Model":first.get("selected_model_candidate"), "Score Model":first.get("selected_score_candidate"),\n            "P1 State Conf":first.get("state_confidence_p1"), "P2 State Conf":first.get("state_confidence_p2"),\n            "P1 Form":first.get("form_logit_p1"), "P2 Form":first.get("form_logit_p2"),\n            "P1 Form Percentile":first.get("form_percentile_p1"), "P2 Form Percentile":first.get("form_percentile_p2"),\n            "P1 Volatility":first.get("day_vol_logit_p1"), "P2 Volatility":first.get("day_vol_logit_p2"),\n            "P1 Volatility Percentile":first.get("vol_percentile_p1"), "P2 Volatility Percentile":first.get("vol_percentile_p2"),\n            "P1 Volatility Label":first.get("volatility_label_p1"), "P2 Volatility Label":first.get("volatility_label_p2"),\n            "P1 State Conf Label":first.get("state_confidence_label_p1"), "P2 State Conf Label":first.get("state_confidence_label_p2"),\n            "Surface Elo P1 %":first.get("elo_probability_p1"),\n            "Matchup Context":_context_summary(first, (("Serve Δ","ctx_serve_dominance_diff"),("Return Δ","ctx_return_dominance_diff"),("Return strength Δ","ctx_return_strength_diff"))),\n            "Workload Context":_context_summary(first, (("Rest Δ","ctx_rest_log1p_diff"),("Games 7d Δ","ctx_games_7d_diff"),("Minutes 7d Δ","ctx_minutes_7d_diff"))),\n            "Travel Context":_context_summary(first, (("Travel km Δ","ctx_travel_km_diff"),("TZ Δ","ctx_timezone_change_abs_diff"))),\n            "Court Context":_context_summary(first, (("Speed×serve Δ","ctx_court_speed_x_serve_dominance_diff"),("Speed×return Δ","ctx_court_speed_x_return_dominance_diff"),("Altitude serve Δ","ctx_big_server_x_altitude"))),\n            "Player State":_context_summary(first, (("Uncertainty Δ","ctx_state_uncertainty_diff"),("Quality Δ","ctx_context_quality_diff"))),\n            "Context Quality A":first.get("context_quality_a"), "Context Quality B":first.get("context_quality_b"),\n            "Weather Source":first.get("weather_source_quality"), "Court Speed Source":first.get("court_speed_source_quality"),\n            "Note":first.get("context_fallback_reason") or "",\n        }\n        for name in [c for c in first.index if str(c).startswith("ctx_")]:\n            row[name] = first.get(name)\n\n        def side_rows(market, selection):\n            subset = group[group.get("market_group", "").astype(str).str.lower().eq(market)].copy()\n            if subset.empty:\n                return subset\n            return subset[subset.get("selection", "").map(canonical_name).eq(canonical_name(selection))]\n\n        for prefix, player in (("P1", p1), ("P2", p2)):\n            ml = _best_production_row(side_rows("moneyline", player))\n            if ml is not None:\n                row[f"{prefix} ML"] = ml.get("best_american_odds")\n                row[f"{prefix} ML EV"] = ml.get("expected_value")\n                row[f"{prefix} ML Signal"] = ml.get("signal")\n            spread = _best_production_row(side_rows("game_spread", player))\n            if spread is not None:\n                row[f"{prefix} Spread"] = spread.get("line")\n                row[f"{prefix} Spread Odds"] = spread.get("best_american_odds")\n                row[f"{prefix} Spread EV"] = spread.get("expected_value")\n                row[f"{prefix} Spread Signal"] = spread.get("signal")\n\n        totals = group[group.get("market_group", "").astype(str).str.lower().eq("total_games")].copy()\n        chosen_total = _best_production_row(totals)\n        if chosen_total is not None:\n            line = chosen_total.get("line")\n            row["Total"] = line\n            same = totals[pd.to_numeric(totals.get("line"), errors="coerce").eq(pd.to_numeric(pd.Series([line]), errors="coerce").iloc[0])]\n            for label, selection in (("Over", "over"), ("Under", "under")):\n                candidate = _best_production_row(same[same.get("selection", "").astype(str).str.lower().eq(selection)])\n                if candidate is not None:\n                    row[f"{label} Odds"] = candidate.get("best_american_odds")\n                    row[f"{label} EV"] = candidate.get("expected_value")\n                    row[f"{label} Signal"] = candidate.get("signal")\n        rows.append(row)\n    return pd.DataFrame(rows)\n'''
    text = text.replace(marker, adapter + marker, 1)
p.write_text(text, encoding="utf-8")


# 3) Today host uses the same production engine; latest automated board is usable immediately.
p = Path("v5_ui_host.py")
text = p.read_text(encoding="utf-8")
text = text.replace('from v5_ui_today import prepare_today_board, render_today_results\n', 'from v5_ui_today import prepare_today_board, production_board_to_today, render_today_results\n', 1)
start = text.index('def _run_daily_board(')
end = text.index('\ndef _render_today_page', start)
new_func = r'''def _run_daily_board(st_module, namespace: Mapping[str, Any], base_dir: Path, market_feed: pd.DataFrame, edited: pd.DataFrame, sims: int) -> pd.DataFrame:\n    from datetime import datetime, timezone\n    from build_v5_context_warehouse import build_context_warehouse\n    from v5_daily_batch import build_daily_outputs, _load_full_context_assets\n\n    load_ratings = _required(namespace, "load_ratings")\n    ratings_by_tour = {"MEN": load_ratings("MEN"), "WTA": load_ratings("WTA")}\n    summary = _read_build_summary(base_dir)\n\n    valid = edited[\n        edited["Player 1"].notna() & edited["Player 2"].notna()\n        & (edited["Player 1"].astype(str).str.strip() != "")\n        & (edited["Player 2"].astype(str).str.strip() != "")\n    ].copy()\n    valid_ids = set(valid.get("Fixture ID", pd.Series(dtype=object)).astype(str))\n    feed = market_feed[market_feed["fixture_id"].astype(str).isin(valid_ids)].copy()\n    override = valid.set_index(valid["Fixture ID"].astype(str))\n    for target, source in (("v5_tour_override","Tour"),("v5_surface_override","Surface"),("v5_best_of_override","Best Of")):\n        values = override[source].to_dict() if source in override.columns else {}\n        feed[target] = feed["fixture_id"].astype(str).map(values)\n\n    status = st_module.empty() if hasattr(st_module, "empty") else None\n    if status is not None:\n        status.write("Building full-context production board…")\n    context_path = base_dir / "context_warehouse" / "player_match_rows.parquet"\n    if not context_path.exists():\n        build_context_warehouse(str(base_dir))\n    context_history, tournament_registry, weather_cache, production_candidate, score_candidate = _load_full_context_assets()\n    production_board, _, errors = build_daily_outputs(\n        feed, ratings_by_tour, summary, existing_ledger=pd.DataFrame(),\n        now=datetime.now(timezone.utc), sims=sims, context_history=context_history,\n        production_candidate=production_candidate, score_candidate=score_candidate,\n        tournament_registry=tournament_registry, weather_cache=weather_cache,\n    )\n    if status is not None:\n        status.empty()\n    if errors and hasattr(st_module, "warning"):\n        st_module.warning(f"{len(errors)} fixture/context issue(s) were flagged by the production engine; affected rows are not silently guessed.")\n    return production_board_to_today(production_board)\n'''
text = text[:start] + new_func + text[end:]
text = text.replace('_run_daily_board(st_module, namespace, base_dir, edited, sims)', '_run_daily_board(st_module, namespace, base_dir, market_feed, edited, sims)', 1)
old = '''    board = st_module.session_state.get("v5_daily_results")\n    if board is None or board.empty:\n        st_module.info("Run the current slate to populate Today with ranked match cards.")\n        return\n'''
new = '''    board = st_module.session_state.get("v5_daily_results")\n    if board is None or board.empty:\n        latest_path = base_dir / "v5_daily_ready" / "latest_board.csv"\n        if latest_path.exists():\n            try:\n                production = pd.read_csv(latest_path, low_memory=False)\n                board = production_board_to_today(production)\n                if board is not None and not board.empty:\n                    st_module.session_state["v5_daily_results"] = board\n            except (OSError, pd.errors.EmptyDataError):\n                board = pd.DataFrame()\n    if board is None or board.empty:\n        st_module.info("No current production board is available yet. Run the current slate to generate one.")\n        return\n'''
if old not in text:
    raise SystemExit("Today default board anchor not found")
text = text.replace(old, new, 1)
p.write_text(text, encoding="utf-8")

print("Applied unified production UI implementation")
